        const result = run(nav, '/reference/second');
        expect(result.tabs.map((tab) => tab.tab)).toEqual(['Guides', 'Reference', 'Support']);
        expect(result.tabs.filter(isActiveDivision).map((tab) => tab.tab)).toEqual(['Reference']);
